"""Runs verify/ui_verify_console_rc06a_v1.js under node with a fake fetch fed from fixtures generated by the RC06a code (correct
install) and from deliberately WRONG installs. Offline; skipped if node is not available. The script itself is READ-ONLY."""
import json, os, shutil, subprocess, sys, tempfile, unittest

HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.join(HERE, "..")
SCRIPT = os.path.join(ROOT, "verify", "ui_verify_console_rc06a_v1.js")
EXPECT_FAIL = {
    "rc05e_installed_pages": {"enhance_service_record_found", "NEW_frame_order_same_at_all_depths", "NEW_trust_table_has_four_columns"},
    "frame_reordered": {"NEW_frame_order_same_at_all_depths"},
    "five_column_table": {"NEW_trust_table_has_four_columns"},
    "frame_reworded_at_enrich": {"NEW_frame_not_reworded_by_depth"},
    "open_question_repeated": {"NEW_open_questions_rolled_up_once"},
    "no_declaration_fingerprint": {"NEW_route_reports_the_declaration_fingerprint"},
}


@unittest.skipUnless(shutil.which("node"), "node not available")
class UiScript(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        p = subprocess.run([sys.executable, os.path.join(HERE, "gen_ui_fixtures_rc06a.py")], capture_output=True, text=True, cwd=HERE, timeout=60)
        assert p.returncode == 0, p.stderr
        cls.fx = json.loads(p.stdout)

    def run_script(self, fixtures):
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as fh:
            json.dump(fixtures, fh)
        p = subprocess.run(["node", os.path.join(HERE, "run_ui_verify.js"), fh.name, SCRIPT], capture_output=True, text=True, timeout=60)
        os.unlink(fh.name)
        self.assertEqual(p.returncode, 0, p.stderr)
        return json.loads(p.stdout)

    def test_correct_install_passes_all_38(self):
        r = self.run_script(self.fx["good"])
        self.assertEqual((r["checks"], r["passed"], r["failed"]), (38, 38, []))

    def test_each_wrong_install_fails_the_check_that_is_meant_to_catch_it(self):
        for name, must in EXPECT_FAIL.items():
            r = self.run_script(self.fx[name])
            failed = {f.split(":")[0] for f in r["failed"]}
            self.assertTrue(must <= failed, (name, must - failed, failed))

    def test_script_is_read_only(self):
        s = open(SCRIPT, encoding="utf-8").read()
        self.assertIn("READ-ONLY", s)
        self.assertEqual(sorted(set(__import__("re").findall(r'post\("(/synapsys/[a-z/]+)"', s))), ["/synapsys/lenses/data", "/synapsys/scaffold/context", "/synapsys/scaffold/view"])
        for bad in ("localStorage", "document.cookie", "document.", "XMLHttpRequest", "method: \"PUT\"", "DELETE"):
            self.assertNotIn(bad, s.replace("credentials", ""))


if __name__ == "__main__":
    unittest.main(verbosity=2)
